const rawData = context.workflow['c20158db-5aa7-460a-9fc7-1a513f7f6218'].result;

const groupedArray = Object.entries(
  rawData.reduce((acc, item) => {
    const group = item.day_group || 'Sin grupo';
    if (!acc[group]) acc[group] = [];
    acc[group].push(item);
    return acc;
  }, {})
).map(([day_group, items]) => ({
  day_group,
  items
}));

return groupedArray;

