const seed = element || 'user';

const allowedColors = [
  '#ff005b', '#ff009d', '#ff00ff', '#ab49ff', '#5d45ff',
  '#0084ff', '#00abf5', '#00b5ff', '#00c2cc', '#00bf76',
  '#00ce2a', '#39d100', '#ffac00', '#ff9300', '#ff5900',
  '#ff002a', '#d8b035', '#da8539', '#00356c', '#1a1a1a'
];

// Hash simple para convertir string en número
function hashString(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    hash = str.charCodeAt(i) + ((hash << 5) - hash);
  }
  return Math.abs(hash);
}

// Selección determinística de color
function getColorFromList(seed, offset = 0) {
  const hash = hashString(seed + offset);
  const index = hash % allowedColors.length;
  return allowedColors[index].replace('#', '');
}

const color1 = getColorFromList(seed, 0);
const color2 = getColorFromList(seed, 1);

const url = `https://api.dicebear.com/9.x/initials/svg?seed=${encodeURIComponent(seed)}&chars=1&radius=50&fontSize=40&backgroundType=gradientLinear&backgroundColor=${color1},${color2}&backgroundRotation=135`;

return url;
